-- READ ONLY supplementary coverage guard for application DDL export.
-- Counts only; no definitions, credentials, account rows or clinical contents returned.
select 'application_collations' as check_name,count(*) as total from pg_collation o join pg_namespace n on n.oid=o.collnamespace where n.nspname in ('public','app') and not exists(select 1 from pg_depend d where d.classid='pg_collation'::regclass and d.objid=o.oid and d.deptype='e')
union all select 'application_text_search_configs',count(*) from pg_ts_config o join pg_namespace n on n.oid=o.cfgnamespace where n.nspname in ('public','app') and not exists(select 1 from pg_depend d where d.classid='pg_ts_config'::regclass and d.objid=o.oid and d.deptype='e')
union all select 'application_text_search_dictionaries',count(*) from pg_ts_dict o join pg_namespace n on n.oid=o.dictnamespace where n.nspname in ('public','app') and not exists(select 1 from pg_depend d where d.classid='pg_ts_dict'::regclass and d.objid=o.oid and d.deptype='e')
union all select 'application_text_search_parsers',count(*) from pg_ts_parser o join pg_namespace n on n.oid=o.prsnamespace where n.nspname in ('public','app') and not exists(select 1 from pg_depend d where d.classid='pg_ts_parser'::regclass and d.objid=o.oid and d.deptype='e')
union all select 'application_text_search_templates',count(*) from pg_ts_template o join pg_namespace n on n.oid=o.tmplnamespace where n.nspname in ('public','app') and not exists(select 1 from pg_depend d where d.classid='pg_ts_template'::regclass and d.objid=o.oid and d.deptype='e')
union all select 'application_casts',count(*) from pg_cast o join pg_type st on st.oid=o.castsource join pg_type tt on tt.oid=o.casttarget join pg_namespace sn on sn.oid=st.typnamespace join pg_namespace tn on tn.oid=tt.typnamespace where (sn.nspname in ('public','app') or tn.nspname in ('public','app')) and not exists(select 1 from pg_depend d where d.classid='pg_cast'::regclass and d.objid=o.oid and d.deptype='e')
union all select 'application_event_triggers',count(*) from pg_event_trigger o join pg_proc p on p.oid=o.evtfoid join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app');
